<template>
    <section class="kw-library">
        <div class="kw-row"><label>{{ label }}<select :value="selected" class="input" @change="changeSelection($event.target)"><option value="">新建{{ label }}</option><option v-for="item in library" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><button class="btn" @click="newItem">新建{{ label }}</button><button class="btn btn-primary" :disabled="busy" @click="save">保存{{ label }}</button><button v-if="draft.id" class="btn btn-danger" :disabled="busy" @click="remove">删除</button></div>
        <p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p v-if="notice" class="workshop-success" role="status">{{ notice }}</p><label>名称<input v-model="draft.name" class="input" maxlength="80" /></label>
        <template v-if="kind==='template'"><label>笔记标题模板<input v-model="draft.data.title" class="input" maxlength="100" /></label><p class="kw-muted">支持 {{ '{'+'{date}'+'}' }} 和 {{ '{'+'{title}'+'}' }} 变量。每日笔记只按日期创建一次；资料库属性作为初始值写入普通笔记。</p><label>正文模板<textarea v-model="draft.data.content" class="input kw-markdown" maxlength="100000" /></label><KbProperties v-model="templateMeta" :databases="databases" :notes="notes" /><button v-if="draft.id" class="btn" :disabled="busy" @click="$emit('create', draft.id)">用此模板新建笔记</button></template>
        <template v-else-if="kind==='block'"><p class="kw-muted">在任意笔记插入 ![[block:编号]]。修改此处后，所有引用在重新读取时同步变化；嵌入不递归。</p><label>同步块正文<textarea v-model="draft.data.content" class="input kw-markdown" maxlength="60000" /></label><label v-if="draft.id">引用语法<input class="input" readonly :value="`![[block:${draft.id}]]`" @focus="$event.target.select()" /></label></template>
        <template v-else><p class="kw-muted">自动动作只在工作台新建笔记或保存属性时触发，一次执行一轮；不会执行系统命令或向外部发送消息。自动动作失败会撤回本次笔记保存。</p><div class="kw-controls"><label>触发条件<select v-model="draft.data.trigger" class="input"><option value="manual">主动点击按钮</option><option value="note-created">工作台新建笔记时</option><option value="property-changed">工作台保存属性时</option></select></label><label>限定资料库<select v-model="draft.data.databaseId" class="input"><option value="">不限资料库</option><option v-for="item in databases" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>执行动作<select v-model="draft.data.action" class="input"><option value="create-note">从模板新建笔记</option><option value="set-property">设置当前笔记属性</option><option value="start-sop">开始SOP清单</option></select></label></div>
            <label v-if="draft.data.action==='create-note'">使用模板<select v-model="draft.data.templateId" class="input"><option value="">选择模板</option><option v-for="item in templates" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label v-else-if="draft.data.action==='start-sop'">SOP模板<select v-model="draft.data.sopId" class="input"><option value="">选择SOP模板</option><option v-for="item in sops" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
            <template v-else><label>要设置的属性<select v-model="draft.data.field" class="input"><option value="">选择属性</option><option v-for="field in actionDatabase?.data.fields.filter(f=>f.type!=='rollup') || []" :key="field.key" :value="field.key">{{ field.label }}</option></select></label><label v-if="actionField?.type==='status'">属性值<select v-model="actionText" class="input"><option v-for="option in actionField.options" :key="option">{{ option }}</option></select></label><label v-else>属性值<input v-model="actionText" class="input" :type="actionField?.type==='number'?'number':actionField?.type==='date'?'date':'text'" /></label><p class="kw-muted">勾选填 true 或 false；多选填 ["选项"]；关联填笔记编号数组；日期范围填 {"start":"2026-11-17","end":"2026-11-18"}。其他类型直接输入文字。</p></template>
            <div v-if="draft.id&&draft.data.trigger==='manual'" class="kw-row"><label>按钮目标笔记<select v-model="targetId" class="input"><option v-for="note in notes" :key="note.id" :value="note.id">{{ note.title }}</option></select></label><button class="btn" :disabled="busy||dirty" @click="runAction">执行此按钮</button><RouterLink v-if="lastResult?.runId" class="btn" :to="`/kb/sops?run=${lastResult.runId}`">打开新清单</RouterLink><button v-if="lastResult?.noteId" class="btn" @click="$emit('open',lastResult.noteId)">打开结果笔记</button></div>
        </template>
    </section>
</template>
<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { kbApi } from '../../api/knowledge-workbench-client.js';
import { sopApi } from '../../api/knowledge-sops-client.js';
import KbProperties from './KbProperties.vue';
const props=defineProps({kind:String,entries:Array,notes:Array,currentId:Number,seed:Object}),emit=defineEmits(['changed','create','open']);
const clone=v=>JSON.parse(JSON.stringify(v)),selected=ref(''),draft=ref(blank()),busy=ref(false),error=ref(''),notice=ref(''),actionText=ref(''),sops=ref([]),targetId=ref(props.currentId||props.notes[0]?.id||null),lastResult=ref(null),baseline=ref('');
const label=computed(()=>({template:'页面模板',block:'同步块',action:'按钮与自动化'}[props.kind])),library=computed(()=>props.entries.filter(e=>e.kind===props.kind)),databases=computed(()=>props.entries.filter(e=>e.kind==='database')),templates=computed(()=>props.entries.filter(e=>e.kind==='template')),actionDatabase=computed(()=>databases.value.find(d=>d.id===draft.value.data.databaseId)),actionField=computed(()=>actionDatabase.value?.data.fields.find(f=>f.key===draft.value.data.field)),dirty=computed(()=>baseline.value!==JSON.stringify([draft.value,actionText.value]));
const templateMeta=computed({get:()=>({databaseId:draft.value.data.databaseId||null,values:draft.value.data.values||{},version:0}),set:value=>{draft.value.data.databaseId=value.databaseId;draft.value.data.values=value.values;}});
function blank(){return{kind:props.kind,name:'新'+({template:'模板',block:'同步块',action:'按钮'}[props.kind]||'项目'),data:props.kind==='template'?{title:'{{date}} 新笔记',content:'',databaseId:null,values:{}}:props.kind==='block'?{content:''}:{trigger:'manual',action:'create-note',databaseId:null,templateId:'',sopId:'',field:'',value:''}};}
let controller=new AbortController(),alive=true,requestId=null;
function select(){const item=library.value.find(e=>e.id===selected.value);draft.value=item?clone(item):blank();actionText.value=typeof draft.value.data.value==='string'?draft.value.data.value:JSON.stringify(draft.value.data.value??'');baseline.value=JSON.stringify([draft.value,actionText.value]);lastResult.value=null;requestId=null;}
function canLeave(){return !busy.value&&(!dirty.value||confirm('编辑内容尚未保存，离开会丢弃。继续？'));}
function changeSelection(selectElement){if(!canLeave()){selectElement.value=selected.value;return;}selected.value=selectElement.value;select();}
function newItem(){if(!canLeave())return;selected.value='';select();}
watch(()=>props.kind,()=>{selected.value='';select();},{immediate:true});
watch(()=>props.seed,seed=>{if(seed){selected.value='';draft.value=clone(seed);actionText.value='';baseline.value='';}},{immediate:true});
watch(()=>library.value.map(e=>e.id+':'+e.version).join(','),()=>{if(!dirty.value){if(selected.value&&!library.value.some(e=>e.id===selected.value))selected.value='';select();}});
if(props.kind==='action')sopApi.templates(controller.signal).then(value=>{if(alive)sops.value=value.items;}).catch(failure=>{if(alive&&!controller.signal.aborted)error.value=failure.message;});
async function operation(task){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await task(controller.signal);if(alive)return result;}catch(failure){if(alive&&!controller.signal.aborted)error.value=failure.message;}finally{if(alive)busy.value=false;}}
async function save(){const value=clone(draft.value);if(props.kind==='action'&&value.data.action==='set-property'){try{value.data.value=['number','check','multi','range','relation'].includes(actionField.value?.type)?JSON.parse(actionText.value):actionText.value;}catch{error.value='属性值格式不正确，请检查数字、勾选值或列表';return;}}const result=await operation(signal=>kbApi.saveEntry(value,signal));if(result){draft.value=result;selected.value=result.id;baseline.value=JSON.stringify([draft.value,actionText.value]);notice.value='已保存';emit('changed');}}
async function remove(){if(!confirm('永久删除此项目？已有引用可能失效。'))return;const result=await operation(signal=>kbApi.remove(draft.value,signal));if(result){selected.value='';select();emit('changed');}}
async function runAction(){requestId ||= crypto.randomUUID();const result=await operation(signal=>kbApi.run(draft.value,targetId.value,requestId,signal));if(result){lastResult.value=result;requestId=null;notice.value='按钮执行成功';emit('changed');}}
onBeforeUnmount(()=>{alive=false;controller.abort();});defineExpose({canLeave,dirty});
</script>
